import pandas as pd
import itertools
import numpy as np

def task_func(animals=None, foods=None):
    is_animals_empty = animals is None or len(animals) == 0
    is_foods_empty = foods is None or len(foods) == 0

    if is_animals_empty and is_foods_empty:
        return pd.DataFrame()

    if is_animals_empty:
        animals = ['Dog', 'Cat', 'Bird']
    if is_foods_empty:
        foods = ['Meat', 'Fish', 'Seeds']

    combos = list(itertools.product(animals, foods))
    np.random.shuffle(combos)

    row_order = []
    col_order = []
    for a, f in combos:
        if a not in row_order:
            row_order.append(a)
        if f not in col_order:
            col_order.append(f)

    df = pd.DataFrame(index=row_order, columns=col_order)
    for a, f in combos:
        df.at[a, f] = f"{a}:{f}"

    return df
